def parse_json(s: str) -> object:
    """
    Parses a JSON string into Python objects using a recursive approach. 
    The parsing handles strings with escape sequences, numbers, booleans, 
    null, arrays, and objects.
    """

    def parse_value(index):
        char = s[index]
        if char == '"':
            return parse_string(index)
        elif char.isdigit() or char == '-':
            return parse_number(index)
        elif s[index:index + 4] == 'true':
            return True, index + 4
        elif s[index:index + 5] == 'false':
            return False, index + 5
        elif s[index:index + 4] == 'null':
            return None, index + 4
        elif char == '[':
            return parse_array(index)
        elif char == '{':
            return parse_object(index)
        raise ValueError("Invalid JSON value")

    def parse_string(index):
        index += 1  # Skip the opening quote
        start_index = index
        while index < len(s):
            char = s[index]
            if char == '"':
                return s[start_index:index], index + 1
            elif char == '\\':
                index += 2  # Skip escape character and next character
            else:
                index += 1
        raise ValueError("Unterminated string")

    def parse_number(index):
        start_index = index
        if s[index] == '-':
            index += 1
        while index < len(s) and s[index].isdigit():
            index += 1
        if index < len(s) and s[index] == '.':
            index += 1
            while index < len(s) and s[index].isdigit():
                index += 1
        num_str = s[start_index:index]
        return float(num_str) if '.' in num_str else int(num_str), index

    def parse_array(index):
        index += 1  # Skip opening bracket
        array = []
        while index < len(s):
            if s[index].isspace():
                index += 1
                continue
            if s[index] == ']':
                return array, index + 1
            value, index = parse_value(index)
            array.append(value)
            while index < len(s) and s[index].isspace():
                index += 1
            if s[index] == ',':
                index += 1
            elif s[index] == ']':
                return array, index + 1
            else:
                raise ValueError("Expected comma or closing bracket in array")
        raise ValueError("Unterminated array")

    def parse_object(index):
        index += 1  # Skip opening brace
        obj = {}
        while index < len(s):
            while index < len(s) and s[index].isspace():
                index += 1
            key, index = parse_string(index)
            while index < len(s) and s[index].isspace():
                index += 1
            if s[index] != ':':
                raise ValueError("Expected colon after key in object")
            index += 1  # Skip the colon
            value, index = parse_value(index)
            obj[key] = value
            while index < len(s) and s[index].isspace():
                index += 1
            if s[index] == ',':
                index += 1
            elif s[index] == '}':
                return obj, index + 1
            else:
                raise ValueError("Expected comma or closing brace in object")
        raise ValueError("Unterminated object")

    parsed_value, final_index = parse_value(0)
    if final_index != len(s):
        raise ValueError("Extra data after JSON input")
